// src/page/history/stage.ts
import { entries as registered, setterOf } from "../observe/registry.js";
async function stageChanges(agent, changes) {
  const onPage = (list) => Array.isArray(list) ? list.filter((c) => !c.offPage && c.component !== "more") : [];
  const components = onPage(agent.snapshot());
  const find = async (ref) => {
    const match = (list) => list.find((c) => c.ref === ref) ?? list.find((c) => c.label === ref);
    return match(components) ?? match(onPage(await agent.query({ within: ref }))) ?? match(onPage(await agent.query({ text: ref })));
  };
  const applied = [];
  for (const change of changes) {
    const component = await find(change.ref);
    const key = change.key ?? "value";
    if (!component || !component.actions.includes(setterOf(key))) {
      continue;
    }
    const result = await agent.act({
      steps: [
        { ref: component.ref, action: setterOf(key), args: [change.value] }
      ]
    });
    if (result.ok) {
      applied.push({
        ref: component.ref,
        key,
        before: component[key],
        value: change.value
      });
    }
  }
  let reverted = false;
  return {
    /** The changes that went on, each with the value it replaced. */
    applied,
    /** Puts back what each control had, and resolves with the changes it couldn't. Runs once. */
    async revert() {
      if (reverted) {
        return [];
      }
      reverted = true;
      const failed = [];
      for (const change of [...applied].reverse()) {
        const { ref, key, before } = change;
        const hidden = before === "[redacted]" && !!registered.get(ref)?.secret;
        const done = !hidden && (await agent.act({
          steps: [{ ref, action: setterOf(key), args: [before] }]
        })).ok;
        if (!done) {
          failed.push(change);
        }
      }
      return failed;
    }
  };
}
export {
  stageChanges
};
